import{_ as r,a0 as p,w as a,s as S,ao as l,I as n,x as t,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如何更新 ISPConfig 3 SSL 证书 | LCTT x X-CMD","titleTemplate":false,"description":"如何更新 ISPConfig 3 SSL 证书 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何更新 ISPConfig 3 SSL 证书 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何更新 ISPConfig 3 SSL 证书 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151208 How to renew the ISPConfig 3 SSL Certificate","title":"如何更新 ISPConfig 3 SSL 证书","tag":"201601","desc":""},"relativePath":"201601/20151208 How to renew the ISPConfig 3 SSL Certificate.md","filePath":"[post].md"}'),f={name:"201601/20151208 How to renew the ISPConfig 3 SSL Certificate.md"};function g(d,e,C,c,u,L){const s=p("Link");return a(),S("div",null,[e[13]||(e[13]=l(`<h1 id="如何更新-ispconfig-3-ssl-证书" tabindex="-1">如何更新 ISPConfig 3 SSL 证书 <a class="header-anchor" href="#如何更新-ispconfig-3-ssl-证书" aria-label="Permalink to “如何更新 ISPConfig 3 SSL 证书”">​</a></h1><p>本教程描述了如何在 ISPConfig 3控制面板中更新 SSL 证书。有两个可选的方法：</p><ul><li>用 OpenSSL 创建一个新的 OpenSSL 证书和 CSR。</li><li>用 ISPConfig updater 更新 SSL 证书</li></ul><p>我将从用手工的方法更新 SSL 证书开始。</p><h3 id="_1-用-openssl-创建一个新的-ispconfig-3-ssl-证书" tabindex="-1">1）用 OpenSSL 创建一个新的 ISPConfig 3 SSL 证书 <a class="header-anchor" href="#_1-用-openssl-创建一个新的-ispconfig-3-ssl-证书" aria-label="Permalink to “1）用 OpenSSL 创建一个新的 ISPConfig 3 SSL 证书”">​</a></h3><p>用 root 用户登录你的服务器。在创建一个新的 SSL 证书之前，先备份现有的。SSL 证书是安全敏感的，因此我将它存储在 /root/ 目录下。</p><pre><code>tar pcfz /root/ispconfig_ssl_backup.tar.gz /usr/local/ispconfig/interface/ssl
chmod 600 /root/ispconfig_ssl_backup.tar.gz
</code></pre><blockquote><p>现在创建一个新的 SSL 证书密钥，证书请求（CSR）和自签发证书。</p></blockquote><pre><code>cd /usr/local/ispconfig/interface/ssl
openssl genrsa -des3 -out ispserver.key 4096
openssl req -new -key ispserver.key -out ispserver.csr
openssl x509 -req -days 3650 -in ispserver.csr \\
-signkey ispserver.key -out ispserver.crt
openssl rsa -in ispserver.key -out ispserver.key.insecure
mv ispserver.key ispserver.key.secure
mv ispserver.key.insecure ispserver.key
</code></pre><p>重启 apache 来加载新的 SSL 证书</p><pre><code>service apache2 restart
</code></pre><h3 id="_2-用-ispconfig-安装器来更新-ssl-证书" tabindex="-1">2）用 ISPConfig 安装器来更新 SSL 证书 <a class="header-anchor" href="#_2-用-ispconfig-安装器来更新-ssl-证书" aria-label="Permalink to “2）用 ISPConfig 安装器来更新 SSL 证书”">​</a></h3><p>另一个获取新的 SSL 证书的替代方案是使用 ISPConfig 更新脚本。下载 ISPConfig 到 /tmp 目录下，解压包并运行脚本。</p><pre><code>cd /tmp
wget http://www.ispconfig.org/downloads/ISPConfig-3-stable.tar.gz
tar xvfz ISPConfig-3-stable.tar.gz
cd ispconfig3_install/install
php -q update.php
</code></pre><p>更新脚本会在更新时询问下面的问题：</p><pre><code>Create new ISPConfig SSL certificate (yes,no) [no]:
</code></pre><p>这里回答“yes”，SSL 证书创建对话框就会启动。</p><hr>`,18)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),o(s,{href:"http://www.faqforge.com/linux/how-to-renew-the-ispconfig-3-ssl-certificate/"},{default:i(()=>[...e[0]||(e[0]=[t("http://www.faqforge.com/linux/how-to-renew-the-ispconfig-3-ssl-certificate/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=t("作者：",-1)),o(s,{href:"http://www.faqforge.com/author/till/"},{default:i(()=>[...e[2]||(e[2]=[t("Till",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:i(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创编译，",-1)),o(s,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const h=r(f,[["render",g]]);export{P as __pageData,h as default};
